int pqcp_runtime_resource_policy_lookup(
	enum pqcp_runtime_resource_condition condition,
	enum pqcp_runtime_command_kind command,
	struct pqcp_runtime_resource_policy_decision *decision)
{
	if (condition < PQCP_RUNTIME_RESOURCE_AVAILABLE ||
	    condition >= PQCP_RUNTIME_RESOURCE_CONDITION_COUNT ||
	    command < PQCP_RUNTIME_COMMAND_NONE ||
	    command >= PQCP_RUNTIME_COMMAND_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = runtime_resource_catalog[condition][command];
	return 0;
}

int pqcp_runtime_resource_policy_catalog_audit(void)
{
	for (size_t condition = 0U;
	     condition < PQCP_RUNTIME_RESOURCE_CONDITION_COUNT;
	     ++condition) {
		for (size_t command = 0U;
		     command < PQCP_RUNTIME_POLICY_COMMAND_COUNT;
		     ++command) {
			const struct pqcp_runtime_resource_policy_decision
				*entry =
					&runtime_resource_catalog
						[condition][command];

			if ((size_t)entry->condition != condition ||
			    (size_t)entry->command != command ||
			    entry->disposition >
				PQCP_RUNTIME_RESOURCE_REQUIRE_RECOVERY ||
			    entry->reason_mask == 0U) {
				return -EBADMSG;
			}
			if (entry->disposition ==
				    PQCP_RUNTIME_RESOURCE_DENY &&
			    entry->error == 0) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}
